export const cphNumberPage = {
  id: 'cphNumber',
  slug: 'cph-number',
  subPage: true,
  maturity: 'detailing'
}

cph: {
  legend: 'CPH number',
  hint: 'For example 12/345/6789',

const isWholeNumberInCounty = (values) => {
  const typed = separatorsStripped(values[COUNTY_FIELD])
  return (
    values[PARISH_FIELD] === '' &&
    values[HOLDING_FIELD] === '' &&
    DIGITS_ONLY.test(typed) &&
    isWholeCphNumber(typed)
  )
}

await expect(page).toHaveTitle(
      `${errorTitlePrefix}${copy.title} - ${serviceName} - ${govukSuffix}`
    )

const checks = (values, { stored } = {}) => {
  if (stored && !isBlank(values) && !isWholeCphNumber(joinParts(values))) {
    return { [COUNTY_FIELD]: copy.errors.cphNoLongerValid }
  }

export const displayedCphNumber = (value) => {
  if (!value) {
    return undefined
  }
  return isWholeCphNumber(value) ? partsOf(value).join('/') : value
}

return render(request, h, invalidJourney, values, { errors }).code(
  HTTP_STATUS_BAD_REQUEST
)

